      "soru": "Jellinek tarafından yapılan sınıflandırmada kişinin devlet tarafından aşılamayacak ve dokunulamayacak özel alanının sınırlarını çizen hak ve hürriyetleri kapsar. Bu haklar kişiyi devlete ve topluma karşı koruyan haklar olduğu için bu haklara \"koruyucu haklar\" da denir. Bu haklar devlete, tarafsız bir tutum, sadece karışmama, \"gölge etmeme\" ödevi yükler. Konut dokunulmazlığı hakkı, kişi güvenliği hakkı, din hürriyeti, düşünce hürriyeti bu kapsamda haklardır.\nYukarıda sözü edilen kavram aşağıdakilerden hangisidir?",
