      "secenekler": ["Herkes, kamu giderlerini karşılamak üzere malî gücüne göre vergi ödemekle yükümlüdür.", "Vergi yükünün adaletli ve dengeli dağılımı maliye politikasının ekonomik amacıdır.", "Vergi, resim, harç ve benzeri malî yükümlülükler kanunla konulur, değiştirilir veya kaldırılır.", "Vergi, resim, harç ve benzeri malî yükümlülüklerin muaflık, istisnalar ve indirimleriyle oranlarına ilişkin hükümlerinde kanunun belirttiği yukarı ve aşağı sınırlar içinde değişiklik yapmak yetkisi Cumhurbaşkanına verilebilir.", "Hiçbiri"],
