      "soru": "Bireysel başvuru ile ilgili aşağıdakilerden hangisi yanlıştır?",
      "secenekler": ["Bireysel başvuru ancak ihlale yol açtığı ileri sürülen işlem, eylem ya da ihmal nedeniyle güncel ve kişisel bir hakkı doğrudan etkilenenler tarafından yapılabilir.", "Kamu tüzel kişileri bireysel başvuru yapamaz. Özel hukuk tüzel kişileri sadece tüzel kişiliğe ait haklarının ihlal edildiği gerekçesiyle bireysel başvuruda bulunabilir.", "Yalnızca Türk vatandaşlarına tanınan haklarla ilgili olarak yabancılar bireysel başvuru yapamaz.", "Bireysel başvurular, kanunda ve İçtüzükte belirtilen şartlara uygun olarak doğrudan ya da mahkemeler veya yurt dışı temsilcilikler vasıtasıyla yapılabilir.", "Bireysel başvurular harca tabi değildir."],
