      "soru": "Anayasa Mahkemesine bireysel başvurunun esas hakkındaki incelenmesiyle ilgili aşağıdakilerden hangisi yanlıştır?",
      "secenekler": ["Kabul edilebilirliğine karar verilen bireysel başvuruların esas incelemesi bölümler tarafından yapılır.", "Başkan iş yükünün bölümler arasında dengeli bir şekilde dağıtılması için gerekli önlemleri alır.", "Bireysel başvurunun kabul edilebilirliğine karar verilmesi hâlinde başvurunun bir örneği bilgi için HSK'ya gönderilir.", "Bölümlerce kanun yolunda gözetilmesi gereken hususlarda inceleme yapılamaz.", "Mahkeme, incelemesini dosya üzerinden yapmakla birlikte gerekli görürse duruşma yapılmasına da karar verebilir."],
