      "secenekler": ["Kabul edilebilirliğine karar verilen bireysel başvuruların esas incelemesi genel kurul tarafından yapılır.", "Bireysel başvurunun kabul edilebilirliğine karar verilmesi hâlinde başvurunun bir örneği bilgi için Adalet Bakanlığına gönderilir.", "Komisyonlar ve bölümler bireysel başvuruları incelerken bir temel hakkın ihlal edilip edilmediğine yönelik her türlü araştırma ve incelemeyi yapabilir.", "Mahkeme, incelemesini dosya üzerinden yapmakla birlikte gerekli görürse duruşma yapılmasına da karar verebilir.", "Bölümler, esas inceleme aşamasında başvurucunun temel haklarının korunması için zorunlu gördükleri tedbirlere resen veya başvurucunun talebi üzerine karar verebilir."],
