      "secenekler": ["Kadın-Erkek Fırsat Eşitliği Komisyonu", "Türkiye İnsan Hakları ve Eşitlik Kurumu", "TBMM İnsan Haklarını İnceleme Komisyonu", "Adalet Komisyonu", "İmar Komisyonu"],
