      "soru": "I. Anayasa Komisyonu\nII. Adalet Komisyonu\nIII. Millî Savunma Komisyonu\nIV. Dışişleri Komisyonu\nV. DDK Komisyonu\nTBMM İçtüzüğünün 20. maddesine göre yukarıdakilerden hangisi TBMM'de yer alan komisyonlardan biri değildir?",
      "secenekler": ["Yalnız V", "I – II – III", "Yalnız I", "Yalnız IV", "I – III"],
      "cevap": "A",
      "aciklama": "\"DDK Komisyonu\" diye bir TBMM komisyonu yoktur; Devlet Denetleme Kurulu Cumhurbaşkanlığına bağlıdır."
