      "secenekler": ["Tüm insanlar özgür, değer ve hak bakımından eşit olarak doğarlar. Akıl ve vicdana sahiptirler. Birbirlerine karşı kardeşlik düşünceleriyle davranmalıdırlar.", "Yaşamak, özgürlük ve kişi güvenliği yalnızca çocuk ve kadınların hakkıdır.", "Hiç kimse kölelik ya da kulluk altında bulundurulamaz; kölelik ve köle ticareti her türlü biçimiyle yasaktır.", "Hiç kimseye işkence yapılamaz; kıyıcı, insanlık dışı, onur kırıcı ceza ve davranışlar uygulanamaz.", "Hiç kimse keyfî olarak tutuklanamaz, alıkonamaz ya da sürülemez."],
