      "unite": 9,
      "zorluk": "orta",
      "soru": "Aşağıdakilerden hangisi AİHM'ye başvuruda kabul edilemezlik sebeplerinden değildir?",
      "secenekler": ["Başvurunun konu bakımından sözleşme veya protokollerinin hükümleriyle bağdaşmaması", "Başvurunun dayanaktan açıkça yoksun olması", "Başvurunun bireysel başvuru hakkının kötüye kullanılması niteliğinde olması", "Başvurunun başka bir başvuru ile esasen aynı olmaması", "Başvurucunun önemli bir zarara uğramamış olması"],
      "cevap": "D",
      "aciklama": "AİHS m.35: Başvurunun daha önce incelenmiş bir başvuruyla \"esasen aynı olması\" kabul edilemezlik sebebidir; aynı olmaması değil."
