      "cevap": "E",
      "aciklama": "AİHS m.35: Daha önce incelenmiş başvuru kabul edilemez. Başvuru süresi 15 No.lu Protokol ile 1 Şubat 2022'den itibaren 6 aydan 4 aya indirilmiştir (kitapta 6 ay yazar)."
