      "soru": "Aşağıdakilerden hangisi AİHM'ye başvuruda kabul edilebilirlik şartlarından biri değildir?",
      "secenekler": ["Dört aylık süre içinde başvurulması", "İsimsiz başvuru yapılmaması", "Başvurunun daha önce AİHM'de incelenmemiş olması", "Başvurunun başka bir başvuru ile esasen aynı olmaması", "Başvurunun konu bakımından sözleşme veya protokollerinin hükümleriyle bağdaşmaması"],
      "cevap": "E",
