      "unite": 9,
      "zorluk": "kolay",
      "soru": "Aşağıdakilerden hangisi AİHS'de yer alan adil yargılanma hakkı için doğru bir bilgi değildir?",
      "secenekler": ["Bir kimse suçluluğu sabit oluncaya kadar suçsuz sayılır.", "Herkes tarafsız ve bağımsız bir mahkeme tarafından makul bir süre içinde hakkaniyete uygun biçimde açık olarak görülmesini isteme hakkına sahiptir.", "Mahkemeler her zaman açık ve serbest olmalı.", "Kişiye yöneltilen suçlamaların nedeni ve niteliği en kısa zamanda anladığı bir dilde anlatılmalı.", "Kendini savunmak, kendi seçeceği bir avukatın yardımından yararlanmak ya da maddi imkânı yoksa mahkeme bir avukat verir."],
      "cevap": "C",
      "aciklama": "AİHS m.6/1: Duruşmalar kural olarak açıktır; ancak genel ahlak, kamu düzeni, millî güvenlik, küçüklerin korunması gibi nedenlerle kapalı yapılabilir."
