      "soru": "Aşağıdakilerden hangisi AİHS'de yer alan adil yargılanma hakkı kapsamında sanığın hakları için yanlış bir bilgidir?",
      "secenekler": ["Savunmasını hazırlamak için gerekli zaman ve kolaylık sağlanmalı.", "İddia tanıklarını sorguya çekmek veya çektirmek, savunma tanıklarının da iddia tanıklarıyla aynı koşullarda dinlenmesini isteme.", "Duruşmada konuşulan dili anlamıyor ya da konuşamıyorsa bir tercüman yardımından ücret karşılığı yararlanma.", "Kendine yöneltilen suçun niteliği ve nedeni en kısa zamanda anlayacağı dilde anlatılma.", "Kendini savunmak, avukat yardımı alma veya maddi imkânı yoksa mahkemeden avukat isteme."],
