      "secenekler": ["Avrupa Konseyi'ne üye ülkelerde demokrasinin yerleşmesini, yaşamasını sağlamak", "Kişilerin temel hak ve özgürlüklerini korumak", "Üye ülkelerin sosyal ve kültürel bakımdan üstün bir düzeye ulaşmasını sağlamak", "Hukukun üstünlüğü ilkesini gerçekleştirmek", "Dünya barışını, güvenliğini korumak"],
